    pub(crate) region_id: String,
    pub(crate) material_id: String,
    pub(crate) thickness: f64,
    pub(crate) node_ids: Vec<String>,
    pub(crate) points: Vec<[f64; 2]>,
    pub(crate) tris: Vec<[u32; 3]>,
}

