/// 🌉️ Hand-written, not derived: `#[derive(ToValue, FromValue)]`'s enum path only supports
/// internally-tagged (`#[value(tag = "…")]`) representations, but `FemDof` is a plain unit-only
/// "string enum" — the value codec's untagged bare-string representation for an enum with no
/// `#[value(...)]` attribute at all — so the wire shape here is just the bare variant name.
impl ToValue for FemDof {
    fn to_value(&self) -> DslValue {
        let name = match self {
            FemDof::Tx => "Tx",
            FemDof::Ty => "Ty",
            FemDof::Tz => "Tz",
            FemDof::Rx => "Rx",
            FemDof::Ry => "Ry",
            FemDof::Rz => "Rz",
        };
        semio_framework_value::DslValue::String(name.to_string())
    }
}
impl FromValue for FemDof {
    fn from_value(value: DslValue) -> Result<Self, ValueError> {
        match value {
            semio_framework_value::DslValue::String(s) => match s.as_str() {
                "Tx" => Ok(FemDof::Tx),
                "Ty" => Ok(FemDof::Ty),
                "Tz" => Ok(FemDof::Tz),
                "Rx" => Ok(FemDof::Rx),
                "Ry" => Ok(FemDof::Ry),
                "Rz" => Ok(FemDof::Rz),
                other => Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, format!("unknown FemDof variant `{other}`"))),
            },
            other => Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, format!("expected a string, found {other:?}"))),
        }
    }
}

